     "ex": "import math\nfrom collections import Counter\n\ndef vec(text):\n    return Counter(text.lower().split())\n\ndef cosine(a, b):\n    dot = sum(a[w] * b[w] for w in a.keys() & b.keys())\n    na = math.sqrt(sum(v * v for v in a.values()))\n    nb = math.sqrt(sum(v * v for v in b.values()))\n    return dot / (na * nb) if na and nb else 0.0\n\nq = vec(\"how do I return a damaged order\")\ndocs = {\n    \"returns\":  \"you can return a damaged order within 14 days\",\n    \"shipping\": \"orders ship within two working days\",\n    \"payment\":  \"we accept cards and cash on delivery\",\n}\nfor name, text in sorted(docs.items(), key=lambda kv: -cosine(q, vec(kv[1]))):\n    print(f\"{cosine(q, vec(text)):.3f}  {name}\")",
